svg.script:
// ====== 1. PASTE YOUR FIREBASE WEB CONFIG HERE (Project settings > Your apps > Web) ======
const firebaseConfig={
  apiKey:"AIzaSyCBtu33YfB7UoCwPSlDz6L483dSK4Dnhy0",
  authDomain:"ripple-646c8.firebaseapp.com",
  // Check this in Firebase console > Realtime Database. If yours shows a different URL
  // (for example ...europe-west1.firebasedatabase.app), paste that here instead.
  databaseURL:"https://ripple-646c8-default-rtdb.firebaseio.com",
  projectId:"ripple-646c8",
  storageBucket:"ripple-646c8.firebasestorage.app",
  messagingSenderId:"287453344639",
  appId:"1:287453344639:web:5598203b7549742a97e04a",
  measurementId:"G-WKVSXH8FTZ"
};
// Image limits: longest side in px, and max size per image in characters (~0.75 bytes each)
const IMG_MAX=1080,IMG_LIMIT=180000,MAX_IMGS=4;
// =========================================================================================

const CONFIGURED=!/YOUR_/.test(firebaseConfig.apiKey);
let auth,db,TS;
if(CONFIGURED){firebase.initializeApp(firebaseConfig);auth=firebase.auth();db=firebase.database();TS=firebase.database.ServerValue.TIMESTAMP}
const $=id=>document.getElementById(id);
const h=(t,a={},...k)=>{const e=document.createElementNS("http://www.w3.org/1999/xhtml",t);for(const[x,v]of Object.entries(a)){if(x==="class")e.className=v;else if(x==="html")e.innerHTML=v;else if(x.startsWith("on"))e[x]=v;else e.setAttribute(x,v)}for(const c of k.flat())if(c!=null&&c!==false)e.append(c);return e};
const P={home:"M3 11l9-8 9 8v10h-6v-6H9v6H3z",search:"M11 4a7 7 0 100 14 7 7 0 000-14zm10 17l-5-5",user:"M12 12a4 4 0 100-8 4 4 0 000 8zM4 21a8 8 0 0116 0",logout:"M9 21H5V3h4M16 17l5-5-5-5M21 12H9",reply:"M21 11.5a8.4 8.4 0 01-8.5 8.5c-1.4 0-2.7-.3-3.9-.9L3 21l1.9-5.4A8.4 8.4 0 1121 11.5z",repost:"M17 2l4 4-4 4M3 11V9a3 3 0 013-3h15M7 22l-4-4 4-4M21 13v2a3 3 0 01-3 3H3",heart:"M20.8 4.6a5.5 5.5 0 00-7.8 0L12 5.7l-1-1.1a5.5 5.5 0 00-7.8 7.8l1 1.1L12 21.2l7.8-7.7 1-1.1a5.5 5.5 0 000-7.8z",share:"M12 15V3m0 0L7 8m5-5l5 5M5 14v5a2 2 0 002 2h10a2 2 0 002-2v-5",image:"M3 5h18v14H3zM8.5 10a1.5 1.5 0 100-3 1.5 1.5 0 000 3zM21 15l-5-5L5 19",back:"M19 12H5m6-6l-6 6 6 6",trash:"M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3",close:"M6 6l12 12M18 6L6 18"};
const ic=n=>`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="${P[n]}"/></svg>`;
const LOGO='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-linecap="round" aria-hidden="true"><circle cx="24" cy="24" r="5" fill="currentColor" stroke="none"/><circle cx="24" cy="24" r="11" stroke-width="3.5" stroke-dasharray="50 19.1" transform="rotate(-30 24 24)"/><circle cx="24" cy="24" r="17.5" stroke-width="3" stroke-dasharray="80 30" transform="rotate(40 24 24)" opacity=".6"/><circle cx="24" cy="24" r="22" stroke-width="2.5" stroke-dasharray="98 40.2" transform="rotate(110 24 24)" opacity=".35"/></svg>';
const fmt=n=>n>=1e6?(n/1e6).toFixed(1)+"M":n>=1e3?(n/1e3).toFixed(1)+"K":""+n;
const ago=t=>{if(typeof t!=="number")return"now";const s=(Date.now()-t)/1e3;return s<60?Math.max(1,s|0)+"s":s<3600?(s/60|0)+"m":s<86400?(s/3600|0)+"h":new Date(t).toLocaleDateString(undefined,{month:"short",day:"numeric"})};
const toast=m=>{const t=$("toast");t.textContent=m;t.classList.add("on");clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove("on"),2200)};
const hue=s=>{let x=0;for(const c of s||"")x=(x*31+c.charCodeAt(0))%360;return x};
const av=(u,s=40)=>h("div",{class:"av",style:`width:${s}px;height:${s}px;background:hsl(${hue(u.handle)} 55% 42%);font-size:${s*.45}px`},(u.name||"?")[0].toUpperCase());
const go=x=>{location.hash=x};

let me=null,store={posts:{}},gOff=[],off=[],refresh=null,onFollow=null,myFollow={},signingUp=false,tab="fyp",cmpEl=null,routeId=0;
const imgCache=new Map();
const imgsFor=id=>{if(!imgCache.has(id))imgCache.set(id,db.ref("imgs/"+id).once("value").then(s=>s.val()||[]));return imgCache.get(id)};
const lightbox=src=>{const l=h("div",{class:"lb",onclick:()=>l.remove()},h("img",{src,alt:"Full size image"}));$("root").append(l)};

// ---- image shrinking: resize + JPEG re-encode until it fits the size budget ----
const loadImg=f=>window.createImageBitmap?createImageBitmap(f):new Promise((ok,no)=>{const i=new Image();i.onload=()=>ok(i);i.onerror=no;i.src=URL.createObjectURL(f)});
async function shrink(f){
  const bmp=await loadImg(f),s=Math.min(1,IMG_MAX/Math.max(bmp.width,bmp.height));
  let w=Math.round(bmp.width*s),hh=Math.round(bmp.height*s),q=.82,out;
  const c=document.createElementNS("http://www.w3.org/1999/xhtml","canvas");
  for(let i=0;i<8;i++){
    c.width=w;c.height=hh;const x=c.getContext("2d");x.fillStyle="#fff";x.fillRect(0,0,w,hh);x.drawImage(bmp,0,0,w,hh);
    out=c.toDataURL("image/jpeg",q);if(out.length<=IMG_LIMIT)break;
    if(q>.52)q-=.1;else{w=Math.round(w*.8);hh=Math.round(hh*.8)}
  }
  return out;
}

// ---- text with #tags, @mentions and links ----
function rich(t){const f=document.createDocumentFragment(),stop=e=>e.stopPropagation();
  t.split(/(#\w+|@\w+|https?:\/\/[^\s]+)/g).forEach(p=>{if(!p)return;
    if(/^#\w+$/.test(p))f.append(h("a",{class:"lnk",href:"#/tag/"+p.slice(1),onclick:stop},p));
    else if(/^@\w+$/.test(p))f.append(h("a",{class:"lnk",href:"#/u/"+p.slice(1).toLowerCase(),onclick:stop},p));
    else if(/^https?:\/\//.test(p))f.append(h("a",{class:"lnk",href:p,target:"_blank",rel:"noopener noreferrer",onclick:stop},p));
    else f.append(p)});return f}

// ---- a single post (or reply, when o.pid is set) ----
function postEl(p,id,o={}){
  const base=o.pid?`replies/${o.pid}/${id}`:`posts/${id}`,lk=p.likes||{},rp=p.reposts||{};
  const act=(cls,ico,n,on,fn,label)=>h("button",{class:`act ${cls}${on?" on":""}`,"aria-label":label,onclick:e=>{e.stopPropagation();fn()}},h("span",{html:ic(ico)}),n?fmt(n):null);
  const acts=h("div",{class:"acts"},
    o.pid?h("span"):act("rep","reply",p.replyCount||0,false,()=>go("#/status/"+id),"Reply"),
    act("rt","repost",Object.keys(rp).length,rp[me.uid],()=>db.ref(base+"/reposts/"+me.uid).set(rp[me.uid]?null:true),"Repost"),
    act("lk","heart",Object.keys(lk).length,lk[me.uid],()=>db.ref(base+"/likes/"+me.uid).set(lk[me.uid]?null:true),"Like"),
    act("sh","share",0,false,()=>{try{navigator.clipboard.writeText(location.href.split("#")[0]+"#/status/"+(o.pid||id))}catch(_){}toast("Link copied")},"Share"));
  const del=p.uid===me.uid?h("button",{class:"act del","aria-label":"Delete post",onclick:e=>{e.stopPropagation();if(confirm("Delete this post?"))removePost(id,o.pid)}},h("span",{html:ic("trash")})):null;
  const imgs=p.ic?h("div",{class:"imgs n"+Math.min(p.ic,4)}):null;
  if(imgs)imgsFor(id).then(a=>{imgs.style.minHeight="0";a.forEach(s=>imgs.append(h("img",{src:s,alt:"Attached image",onclick:e=>{e.stopPropagation();lightbox(s)}})))}).catch(()=>{});
  const stop=e=>e.stopPropagation();
  return h("article",{class:"post"+(o.detail?" det":""),onclick:()=>{if(!o.pid&&!o.detail)go("#/status/"+id)}},
    h("a",{href:"#/u/"+p.handle,onclick:stop},av(p,o.detail?48:40)),
    h("div",{class:"pb"},
      h("div",{class:"ph"},h("a",{href:"#/u/"+p.handle,onclick:stop},h("b",{},p.name)),h("span",{},"@"+p.handle+" · "+ago(p.ts)),del),
      p.text?h("div",{class:"pt"},rich(p.text)):null,imgs,
      o.detail?h("div",{class:"when"},typeof p.ts==="number"?new Date(p.ts).toLocaleString():""):null,
      acts));
}
async function removePost(id,pid){
  try{if(pid){await db.ref(`replies/${pid}/${id}`).remove();db.ref("posts/"+pid+"/replyCount").transaction(n=>Math.max(0,(n||1)-1))}
    else{await db.ref("posts/"+id).remove();if(location.hash.includes("/status/"))go("#/")}
    db.ref("imgs/"+id).remove().catch(()=>{});toast("Post deleted")}catch(e){toast(e.message)}}

// ---- composer (new post or reply) ----
function compose({pid,ph="What is happening?!",btn="Post"}={}){
  let imgs=[],busy=false;
  const ta=h("textarea",{placeholder:ph,rows:"1","aria-label":ph}),prev=h("div",{class:"prev"}),file=h("input",{type:"file",accept:"image/*",multiple:"",hidden:""});
  const cnt=h("span",{class:"cnt"}),post=h("button",{class:"btn",onclick:submit},btn);
  const pick=h("button",{class:"icn","aria-label":"Add images",onclick:()=>file.click(),html:ic("image")});
  function upd(){const n=ta.value.length,left=280-n,col=left<0?"#f4212e":left<=20?"#ffd400":"var(--blue)";
    cnt.innerHTML=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><circle cx="10" cy="10" r="8" fill="none" stroke="var(--line)" stroke-width="2"/><circle cx="10" cy="10" r="8" fill="none" stroke="${col}" stroke-width="2" stroke-dasharray="50.3" stroke-dashoffset="${50.3*(1-Math.min(n,280)/280)}" transform="rotate(-90 10 10)"/></svg>${left<=20?`<i>${left}</i>`:""}`;
    cnt.style.display=n?"flex":"none";post.disabled=busy||left<0||(!ta.value.trim()&&!imgs.length);pick.disabled=busy||imgs.length>=MAX_IMGS}
  const draw=()=>{prev.replaceChildren(...imgs.map((s,i)=>h("div",{class:"pv"},h("img",{src:s,alt:"Selected image"}),h("button",{"aria-label":"Remove image",onclick:()=>{imgs.splice(i,1);draw()},html:ic("close")}))));upd()};
  ta.oninput=()=>{ta.style.height="auto";ta.style.height=ta.scrollHeight+"px";upd()};
  ta.onkeydown=e=>{if(e.key==="Enter"&&(e.ctrlKey||e.metaKey))submit()};
  file.onchange=async()=>{const fs=[...file.files].slice(0,MAX_IMGS-imgs.length);file.value="";busy=true;upd();
    try{for(const f of fs)imgs.push(await shrink(f))}catch(e){toast("Couldn’t read that image")}busy=false;draw()};
  async function submit(){
    const text=ta.value.trim();if(busy||(!text&&!imgs.length)||text.length>280)return;busy=true;upd();
    const d={uid:me.uid,name:me.name,handle:me.handle,ts:TS};if(text)d.text=text;if(imgs.length)d.ic=imgs.length;
    try{const r=pid?db.ref("replies/"+pid).push():db.ref("posts").push();
      if(imgs.length){imgCache.set(r.key,Promise.resolve(imgs));await db.ref("imgs/"+r.key).set(imgs)}
      await r.set(d);if(pid)db.ref("posts/"+pid+"/replyCount").transaction(n=>(n||0)+1);
      ta.value="";imgs=[];ta.style.height="auto";draw()}catch(e){toast(e.message)}
    busy=false;upd()}
  const el=h("div",{class:"cmp"},av(me),h("div",{class:"cw"},ta,prev,h("div",{class:"cb"},h("div",{class:"tools"},pick),h("div",{class:"tools"},cnt,post)),file));
  el.ta=ta;upd();return el;
}

// ---- views ----
const sorted=()=>Object.entries(store.posts).sort((a,b)=>(b[1].ts||0)-(a[1].ts||0));
const fill=(list,arr,empty)=>list.replaceChildren(...(arr.length?arr.map(([id,p])=>postEl(p,id)):[h("div",{class:"empty"},empty)]));
const nav=k=>document.querySelectorAll("#nav .nv").forEach(a=>a.classList.toggle("on",a.dataset.k===k));

function home(){
  nav("home");
  const c=cmpEl=compose(),list=h("div"),tabs=h("div",{class:"tabs"});
  [["fyp","For you"],["fol","Following"]].forEach(([k,t])=>tabs.append(h("button",{class:tab===k?"on":"",onclick:()=>{tab=k;[...tabs.children].forEach(b=>b.classList.toggle("on",b.textContent===t));refresh()}},t)));
  $("main").append(h("div",{class:"hd"},tabs),c,list);
  refresh=()=>fill(list,sorted().filter(([,p])=>tab==="fyp"||p.uid===me.uid||myFollow[p.uid]),tab==="fol"?"Follow people to see their posts here.":"No posts yet. Be the first to post.");
  refresh();
}
function search(q){
  nav("search");
  const inp=h("input",{class:"srch",placeholder:"Search posts","aria-label":"Search posts"}),list=h("div");inp.value=q;
  inp.onkeydown=e=>{if(e.key==="Enter")go("#/search/"+encodeURIComponent(inp.value.trim()))};
  $("main").append(h("div",{class:"hd pad"},inp),list);
  refresh=()=>{const n=q.toLowerCase();fill(list,q?sorted().filter(([,p])=>(p.text||"").toLowerCase().includes(n)||(p.handle||"").includes(n)||(p.name||"").toLowerCase().includes(n)):[],q?"No results for “"+q+"”":"Search the latest posts.")};
  refresh();if(!q)inp.focus();
}
function status(id){
  nav("");
  const top=h("div"),list=h("div"),c=compose({pid:id,ph:"Post your reply",btn:"Reply"});
  $("main").append(h("div",{class:"hd row"},h("button",{class:"icn","aria-label":"Back",onclick:()=>history.length>1?history.back():go("#/"),html:ic("back")}),h("b",{},"Post")),top,c,list);
  const r1=db.ref("posts/"+id),r2=db.ref("replies/"+id);
  const f1=s=>{const p=s.val();top.replaceChildren(p?postEl(p,id,{detail:true}):h("div",{class:"empty"},"This post doesn’t exist."))};
  const f2=s=>{const a=[];s.forEach(x=>{a.push([x.key,x.val()])});a.sort((x,y)=>(x[1].ts||0)-(y[1].ts||0));list.replaceChildren(...a.map(([k,p])=>postEl(p,k,{pid:id})))};
  r1.on("value",f1);r2.on("value",f2);off.push(()=>r1.off("value",f1),()=>r2.off("value",f2));
}
async function profile(handle){
  const rid=routeId,main=$("main");nav(handle===me.handle?"me":"");
  main.append(h("div",{class:"empty"},"Loading…"));
  let uid,u;try{uid=(await db.ref("usernames/"+handle).once("value")).val();u=uid&&(await db.ref("users/"+uid).once("value")).val()}catch(e){}
  if(rid!==routeId)return;main.replaceChildren();
  if(!u){main.append(h("div",{class:"empty"},"This account doesn’t exist."));return}
  const list=h("div"),cnt=h("small"),fb=h("button",{class:"btn fol"}),fc=h("span",{class:"dim"});
  const paint=()=>{fb.textContent=myFollow[uid]?"Following":"Follow";fb.classList.toggle("on",!!myFollow[uid]);fc.textContent=Object.keys(uid===me.uid?myFollow:u.following||{}).length+" Following"};
  fb.onclick=()=>db.ref(`users/${me.uid}/following/${uid}`).set(myFollow[uid]?null:true);
  paint();onFollow=paint;
  main.append(h("div",{class:"hd row"},h("button",{class:"icn","aria-label":"Back",onclick:()=>history.length>1?history.back():go("#/"),html:ic("back")}),h("div",{},h("b",{},u.name),cnt)),
    h("div",{class:"ban"}),
    h("div",{class:"pinfo"},h("div",{class:"prow"},av(u,96),uid===me.uid?null:fb),h("b",{style:"font-size:20px"},u.name),h("div",{class:"dim"},"@"+u.handle),
      h("div",{class:"dim",style:"margin-top:10px"},"Joined "+(u.ts?new Date(u.ts).toLocaleDateString(undefined,{month:"long",year:"numeric"}):"recently")+" · ",fc)),list);
  const q=db.ref("posts").orderByChild("uid").equalTo(uid);
  const f=s=>{const a=[];s.forEach(x=>{a.push([x.key,x.val()])});a.sort((x,y)=>(y[1].ts||0)-(x[1].ts||0));cnt.textContent=a.length+(a.length===1?" post":" posts");fill(list,a,"No posts yet.")};
  q.on("value",f);off.push(()=>q.off("value",f));
}
function route(){
  off.splice(0).forEach(f=>f());refresh=null;onFollow=null;cmpEl=null;routeId++;
  const m=location.hash.slice(1)||"/",main=$("main");main.replaceChildren();$("root").scrollTop=0;let r;
  if(r=m.match(/^\/status\/([-\w]+)/))status(r[1]);
  else if(r=m.match(/^\/u\/(\w+)/))profile(r[1].toLowerCase());
  else if(r=m.match(/^\/search\/?(.*)/))search(decodeURIComponent(r[1]));
  else if(r=m.match(/^\/tag\/(\w+)/))search("#"+r[1]);
  else home();
}
window.addEventListener("hashchange",()=>me&&route());

// ---- sidebar widgets ----
function trends(){
  const c={};Object.values(store.posts).forEach(p=>((p.text||"").match(/#\w+/g)||[]).forEach(t=>{t=t.toLowerCase();c[t]=(c[t]||0)+1}));
  const a=Object.entries(c).sort((x,y)=>y[1]-x[1]).slice(0,5);
  $("trends").replaceChildren(h("h2",{},"What’s happening"),...(a.length?a.map(([t,n])=>h("a",{class:"tr",href:"#/tag/"+t.slice(1)},h("div",{},h("b",{},t),h("small",{},n+(n>1?" posts":" post"))))):[h("div",{class:"tr dim"},"Hashtags will show up here.")]));
}
async function who(){
  try{const s=await db.ref("users").orderByChild("ts").limitToLast(8).once("value"),a=[];
    s.forEach(x=>{if(x.key!==me.uid&&!myFollow[x.key])a.push(x.val())});a.reverse();
    $("who").replaceChildren(h("h2",{},"New on Ripple"),...(a.length?a.slice(0,3).map(u=>h("a",{class:"tr",href:"#/u/"+u.handle},av(u),h("div",{},h("b",{},u.name),h("small",{},"@"+u.handle)))):[h("div",{class:"tr dim"},"No one new yet.")]))}catch(e){}
}

// ---- auth + boot ----
const authErr=e=>{const c=e.code||"",m=String(e.message||e);
  return({"auth/email-already-in-use":"That email already has an account. Try signing in.","auth/invalid-email":"That email address doesn’t look right.","auth/weak-password":"Password must be at least 6 characters.","auth/invalid-credential":"Wrong email or password.","auth/wrong-password":"Wrong email or password.","auth/user-not-found":"Wrong email or password.","auth/missing-password":"Enter your password.","auth/too-many-requests":"Too many attempts. Wait a moment and try again.","auth/operation-not-allowed":"Email/Password sign-in is off. Turn it on in Firebase > Authentication > Sign-in method.","auth/network-request-failed":"Network error. Check your connection."})[c]||(/permission_denied/i.test(m)?"The database rules block this. Publish the rules in Firebase > Realtime Database > Rules.":m.replace("Firebase: ",""))};
function authUI(mode){
  const a=$("auth"),up=mode==="up";a.hidden=false;$("app").hidden=true;
  if(!CONFIGURED){a.replaceChildren(h("div",{class:"card"},h("div",{class:"lg",html:LOGO}),h("h1",{},"Set up Firebase"),h("p",{class:"dim"},"Paste your Firebase web config into the firebaseConfig object at the top of this file’s script, then reload.")));return}
  const err=h("div",{class:"err"}),f={},btn=h("button",{class:"btn big",onclick:submit},up?"Create account":"Sign in");
  const fs=[...(up?[["name","Name"],["handle","Handle (letters, numbers, _)"]]:[]),["email","Email","email"],["pw","Password (6+ characters)","password"]];
  a.replaceChildren(h("div",{class:"card"},h("div",{class:"brand"},h("div",{class:"lg",html:LOGO}),h("span",{},"Ripple")),h("h1",{},"Make a ripple."),h("h2",{},up?"Join Ripple today.":"Sign in to Ripple."),
    ...fs.map(([k,p,t])=>f[k]=h("input",{class:"in",placeholder:p,type:t||"text","aria-label":p,autocomplete:({name:"name",handle:"username",email:"email",pw:up?"new-password":"current-password"})[k],onkeydown:e=>{if(e.key==="Enter")submit()}})),
    err,btn,h("p",{class:"dim"},up?"Already have an account? ":"New here? ",h("a",{class:"lnk",href:"#",onclick:e=>{e.preventDefault();authUI(up?"in":"up")}},up?"Sign in":"Create account"))));
  async function submit(){
    err.textContent="";btn.disabled=true;
    try{const email=f.email.value.trim(),pw=f.pw.value;
      if(!up){await auth.signInWithEmailAndPassword(email,pw);return}
      const name=f.name.value.trim(),handle=f.handle.value.trim().toLowerCase();
      if(!name)throw Error("Enter your name.");
      if(!/^[a-z0-9_]{3,15}$/.test(handle))throw Error("Handle must be 3–15 letters, numbers or underscores.");
      if((await db.ref("usernames/"+handle).once("value")).exists())throw Error("That handle is taken.");
      signingUp=true;const cred=await auth.createUserWithEmailAndPassword(email,pw);
      try{
        const t=await db.ref("usernames/"+handle).transaction(c=>c===null?cred.user.uid:undefined);
        if(!t.committed)throw Error("That handle is taken.");
        await db.ref("users/"+cred.user.uid).set({name,handle,ts:TS});
      }catch(e){await db.ref("usernames/"+handle).remove().catch(()=>{});await cred.user.delete().catch(()=>{});throw e}
      signingUp=false;boot(cred.user);
    }catch(e){signingUp=false;err.textContent=authErr(e)}
    btn.disabled=false}
}
async function boot(u){
  try{const s=await db.ref("users/"+u.uid).once("value");if(!s.exists())throw Error("Profile not found. Create an account first.");me={uid:u.uid,...s.val()}}
  catch(e){toast(e.message);auth.signOut();return}
  $("auth").hidden=true;$("app").hidden=false;
  document.querySelector(".logo").innerHTML=LOGO;
  $("nav").replaceChildren(...[["home","Home","#/","home"],["search","Explore","#/search/","search"],["me","Profile","#/u/"+me.handle,"user"]].map(([k,t,href,i])=>h("a",{class:"nv","data-k":k,href},h("span",{html:ic(i)}),h("span",{class:"lb2"},t))),
    h("button",{class:"nv",onclick:()=>auth.signOut()},h("span",{html:ic("logout")}),h("span",{class:"lb2"},"Log out")));
  const chip=$("meChip");chip.href="#/u/"+me.handle;chip.replaceChildren(av(me),h("div",{class:"lb2"},h("b",{},me.name),h("small",{},"@"+me.handle)));
  const pr=db.ref("posts").limitToLast(150),fr=db.ref("users/"+u.uid+"/following");
  const f1=s=>{store.posts=s.val()||{};if(refresh)refresh();trends()};
  const f2=s=>{myFollow=s.val()||{};if(onFollow)onFollow();if(refresh)refresh()};
  pr.on("value",f1);fr.on("value",f2);gOff.push(()=>pr.off("value",f1),()=>fr.off("value",f2));
  who();route();
}
$("postBtn").onclick=()=>{const focus=()=>cmpEl&&cmpEl.ta.focus();if(cmpEl)focus();else{go("#/");setTimeout(focus,120)}};
$("q").onkeydown=e=>{if(e.key==="Enter")go("#/search/"+encodeURIComponent(e.target.value.trim()))};
if(CONFIGURED){
  auth.onAuthStateChanged(u=>{if(signingUp)return;gOff.splice(0).forEach(f=>f());off.splice(0).forEach(f=>f());me=null;store.posts={};myFollow={};if(u)boot(u);else authUI("in")});
}else authUI("in");
